// Extract user message and build context
const body = $input.first().json.body;
const userMessage = body.message || '';
const dashboardState = body.state || {};

// Build context from dashboard state
let contextLines = [];
if (dashboardState.healthScores) {
  const scores = dashboardState.healthScores;
  contextLines.push('Current Node Health Scores:');
  Object.entries(scores).forEach(([id, score]) => {
    const status = score >= 80 ? 'Healthy' : score >= 50 ? 'Warning' : score < 30 ? 'Critical' : 'Danger';
    contextLines.push(`  Node #${id}: ${score}/100 (${status})`);
  });
}
if (dashboardState.totalEvents !== undefined) {
  contextLines.push(`Total Events Processed: ${dashboardState.totalEvents}`);
}
if (dashboardState.anomalyCount !== undefined) {
  contextLines.push(`Anomalies Detected: ${dashboardState.anomalyCount}`);
}
if (dashboardState.alerts && dashboardState.alerts.length > 0) {
  contextLines.push('Recent Alerts:');
  dashboardState.alerts.slice(-5).forEach(a => {
    contextLines.push(`  - ${a.severity}: ${a.message} (Node #${a.node_id})`);
  });
}

const context = contextLines.join('\n');

return [{
  json: {
    userMessage,
    context,
    dashboardState
  }
}];

// Format LLM response for dashboard
const response = $input.first().json;
let aiMessage = 'Üzgünüm, şu an yanıt üretemiyorum.';

try {
  if (response.choices && response.choices[0]) {
    aiMessage = response.choices[0].message.content;
  }
} catch (e) {
  aiMessage = 'Bir hata oluştu: ' + e.message;
}

return [{
  json: {
    reply: aiMessage,
    model: 'llama-3.3-70b-versatile',
    timestamp: new Date().toISOString()
  }
}];
